// Eight generated frames, triggered by an actual verdict hit; never modifies combat data.
const balanceVfxSheet=new Image();balanceVfxSheet.assetSrc='assets/balance-verdict-vfx-v1.png';BASE_GAME_IMAGES.push(balanceVfxSheet);GAME_IMAGES.push(balanceVfxSheet);
let balanceVfx=[],balanceVfxOwner=null,balanceVfxResolving=false;
function resetBalanceVfx(){balanceVfx=[];balanceVfxOwner=p;}
function addBalanceVfx(x,y){if(balanceVfxOwner!==p)resetBalanceVfx();if(!started||paused||dead||presentationPrefs.reduced||!Number.isFinite(x)||!Number.isFinite(y))return;let limit=effectQuality==='low'?1:2;while(balanceVfx.length>=limit)balanceVfx.shift();balanceVfx.push({x,y,time:0,duration:.56});}
function stepBalanceVfx(dt){if(balanceVfxOwner!==p||!started||dead||presentationPrefs.reduced){resetBalanceVfx();return;}if(paused||!Number.isFinite(dt)||dt<=0)return;for(let e of balanceVfx)e.time+=dt;balanceVfx=balanceVfx.filter(e=>e.time<e.duration).slice(-(effectQuality==='low'?1:2));}
function paintBalanceVfx(){if(!started||dead||presentationPrefs.reduced||balanceVfxOwner!==p||!balanceVfxSheet.complete||!balanceVfxSheet.naturalWidth||!balanceVfxSheet.naturalHeight)return;let low=effectQuality==='low',sw=balanceVfxSheet.naturalWidth/4,sh=balanceVfxSheet.naturalHeight/2,limit=low?1:2,size=210;for(let e of balanceVfx.slice(-limit)){if(!visibleAt(e.x,e.y))continue;let q=project(e.x,e.y);if(q.x<-size||q.x>W+size||q.y<-size||q.y>H+size)continue;let t=clamp(e.time/e.duration,0,1),frame=low?Math.min(3,Math.floor(t*4))*2:Math.min(7,Math.floor(t*8));ctx.save();ctx.globalCompositeOperation='screen';ctx.globalAlpha=t>.75?(1-t)*4:1;ctx.drawImage(balanceVfxSheet,(frame%4)*sw,Math.floor(frame/4)*sh,sw,sh,q.x-size/2,q.y-size*.86,size,size);ctx.restore();}}
const balanceVfxHitBase=spellHit;spellHit=(e,d,b)=>{let hp=e?.hp,hits=e?.trainingHits||0,eligible=!balanceVfxResolving&&b?.type==='crafted_3_2'&&!e?.dotTick,previous=balanceVfxResolving,result;balanceVfxResolving=true;try{result=balanceVfxHitBase(e,d,b);}finally{balanceVfxResolving=previous;}if(eligible&&(e.hp<hp||(e.trainingHits||0)>hits))addBalanceVfx(e.x,e.y);return result;};
const balanceVfxUpdateBase=update;update=dt=>{stepBalanceVfx(dt);return balanceVfxUpdateBase(dt);};
const balanceVfxDrawBase=drawEffects;drawEffects=()=>{let result=balanceVfxDrawBase();paintBalanceVfx();return result;};
const balanceVfxWorldBase=loadWorld;loadWorld=(...args)=>{resetBalanceVfx();return balanceVfxWorldBase(...args);};
const balanceVfxDummyBase=clearDummy;clearDummy=(...args)=>{resetBalanceVfx();return balanceVfxDummyBase(...args);};
